                post_hook={
                    "sql": "CREATE TABLE IF NOT EXISTS public.utm_mapping ( utm_source VARCHAR, utm_medium VARCHAR, channel VARCHAR, source VARCHAR ); DROP TABLE IF EXISTS public.tuco_kids_shopify_utm_parameters; CREATE TABLE public.tuco_kids_shopify_utm_parameters AS SELECT shopifyql.*, UPPER(utm_mapping.channel) as shopifyql_mapped_channel, UPPER(utm_mapping.source) as shopifyql_mapped_source FROM ( SELECT * FROM ( SELECT a.id, a.name, a.createdat, CAST(a.customerjourneysummary.momentscount AS INT) moments_count, CAST(a.customerjourneysummary.daystoconversion AS INT) daystoconvert, CAST(a.customerjourneysummary.lastvisit.utmparameters.source AS VARCHAR) lastvisit_utm_source, CAST(a.customerjourneysummary.lastvisit.utmparameters.medium AS VARCHAR) lastvisit_utm_medium, CAST(a.customerjourneysummary.lastvisit.source AS VARCHAR) lastvisit_non_utm_source, CAST(a.customerjourneysummary.lastvisit.utmparameters.campaign AS VARCHAR) lastvisit_utm_campaign, CAST(a.customerjourneysummary.firstvisit.utmparameters.source AS VARCHAR) firstvisit_utm_source, CAST(a.customerjourneysummary.firstvisit.utmparameters.medium AS VARCHAR) firstvisit_utm_medium, CAST(a.customerjourneysummary.firstvisit.utmparameters.campaign AS VARCHAR) firstvisit_utm_campaign, REPLACE(cast(b.id as varchar), \'gid://shopify/CustomerVisit/\', \'\') AS moment_id, b.utmparameters.source::varchar last_moment_utm_source, b.utmparameters.medium::varchar last_moment_utm_medium, CASE WHEN CAST(a.customerjourneysummary.momentscount AS INT) > 1 THEN CAST(a.customerjourneysummary.lastvisit.utmparameters.source AS VARCHAR) ELSE CAST(a.customerjourneysummary.firstvisit.utmparameters.source AS VARCHAR) END cjsummary_utm_source, a.referrerdisplaytext referrer_name, a.customerjourneysummary, a.customerjourney, COALESCE(b.utmparameters.source::varchar, CAST(a.customerjourneysummary.lastvisit.utmparameters.source AS VARCHAR), CAST(a.customerjourneysummary.lastvisit.source AS VARCHAR)) shopifyql_unmapped_last_source, COALESCE(b.utmparameters.medium::varchar, CAST(a.customerjourneysummary.lastvisit.utmparameters.medium AS VARCHAR)) shopifyql_unmapped_last_medium, ROW_NUMBER() OVER (PARTITION BY a.name ORDER BY REPLACE(cast(b.id as varchar), \'gid://shopify/CustomerVisit/\', \'\') DESC) rw FROM public.shopify_tuco_kids_utm_parameters a CROSS JOIN a.customerjourney.moments AS b ) WHERE rw = 1 ) shopifyql LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY LOWER(COALESCE(utm_source, \'\') || COALESCE(utm_medium, \'\')) ORDER BY 1) rw FROM public.utm_mapping ) WHERE rw = 1 AND LOWER(COALESCE(utm_source, \'\') || COALESCE(utm_medium, \'\')) IS NOT NULL ) utm_mapping ON LOWER(TRIM(COALESCE(shopifyql.shopifyql_unmapped_last_source::varchar, \'\'))) = LOWER(TRIM(COALESCE(utm_mapping.utm_source::varchar, \'\'))) AND LOWER(TRIM(COALESCE(shopifyql.shopifyql_unmapped_last_medium::varchar, \'\'))) = LOWER(TRIM(COALESCE(utm_mapping.utm_medium::varchar, \'\'))); DROP TABLE IF EXISTS public.tuco_kids_checkout_source; CREATE TABLE public.tuco_kids_checkout_source AS WITH checkout AS ( WITH utm_source_cte AS ( SELECT s.id, UPPER(a.value::varchar) AS utm_source FROM public.Tuco_Kids_new_shopify_orders_manual s CROSS JOIN s.note_attributes AS a WHERE (LOWER(json_serialize(s.note_attributes)) LIKE \'%gokwik%\' OR LOWER(json_serialize(s.note_attributes)) LIKE \'%shopflo%\' OR LOWER(s.tags) LIKE \'%gokwik%\' OR LOWER(s.tags) LIKE \'%shopflo%\') AND LOWER(a.name::varchar) = \'utm_source\' ), utm_medium_cte AS ( SELECT s.id, UPPER(a.value::varchar) AS utm_medium FROM public.Tuco_Kids_new_shopify_orders_manual s CROSS JOIN s.note_attributes a WHERE (LOWER(json_serialize(s.note_attributes)) LIKE \'%gokwik%\' OR LOWER(json_serialize(s.note_attributes)) LIKE \'%shopflo%\' OR LOWER(s.tags) LIKE \'%gokwik%\' OR LOWER(s.tags) LIKE \'%shopflo%\') AND LOWER(a.name::varchar) = \'utm_medium\' ), utm_campaign_cte AS ( SELECT s.id, UPPER(a.value::varchar) AS utm_campaign FROM public.Tuco_Kids_new_shopify_orders_manual s CROSS JOIN s.note_attributes a WHERE (LOWER(json_serialize(s.note_attributes)) LIKE \'%gokwik%\' OR LOWER(json_serialize(s.note_attributes)) LIKE \'%shopflo%\' OR LOWER(s.tags) LIKE \'%gokwik%\' OR LOWER(s.tags) LIKE \'%shopflo%\') AND LOWER(a.name::varchar) = \'utm_campaign\' ), utm_content_cte AS ( SELECT s.id, UPPER(a.value::varchar) AS utm_content FROM public.Tuco_Kids_new_shopify_orders_manual s CROSS JOIN s.note_attributes a WHERE (LOWER(json_serialize(s.note_attributes)) LIKE \'%gokwik%\' OR LOWER(json_serialize(s.note_attributes)) LIKE \'%shopflo%\' OR LOWER(s.tags) LIKE \'%gokwik%\' OR LOWER(s.tags) LIKE \'%shopflo%\') AND LOWER(a.name::varchar) = \'utm_content\' ) SELECT s.id, s.tags, source_cte.utm_source AS checkout_utm_source, medium_cte.utm_medium AS checkout_utm_medium, campaign_cte.utm_campaign AS checkout_utm_campaign, content_cte.utm_content AS checkout_utm_content FROM public.Tuco_Kids_new_shopify_orders_manual s LEFT JOIN utm_source_cte source_cte ON s.id = source_cte.id LEFT JOIN utm_medium_cte medium_cte ON s.id = medium_cte.id LEFT JOIN utm_campaign_cte campaign_cte ON s.id = campaign_cte.id LEFT JOIN utm_content_cte content_cte ON s.id = content_cte.id WHERE (LOWER(json_serialize(s.note_attributes)) LIKE \'%gokwik%\' OR LOWER(json_serialize(s.note_attributes)) LIKE \'%shopflo%\' OR LOWER(s.tags) LIKE \'%gokwik%\' OR LOWER(s.tags) LIKE \'%shopflo%\') ) SELECT checkout.*, UPPER(utm_mapping.channel) as checkout_mapped_channel, UPPER(utm_mapping.source) as checkout_mapped_source FROM checkout LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY LOWER(COALESCE(utm_source, \'\') || COALESCE(utm_medium, \'\')) ORDER BY 1) rw FROM public.utm_mapping ) WHERE rw = 1 AND LOWER(COALESCE(utm_source, \'\') || COALESCE(utm_medium, \'\')) IS NOT NULL ) utm_mapping ON LOWER(TRIM(COALESCE(checkout.checkout_utm_source, \'\'))) = LOWER(TRIM(COALESCE(utm_mapping.utm_source, \'\'))) AND LOWER(TRIM(COALESCE(checkout.checkout_utm_medium, \'\'))) = LOWER(TRIM(COALESCE(utm_mapping.utm_medium, \'\'))) ; DROP TABLE IF EXISTS public.shopify_Tuco_Kids_all_customers; CREATE TABLE public.Shopify_Tuco_Kids_all_customers AS SELECT *, \'WEBSITE\' AS shop_name FROM public.Tuco_Kids_new_shopify_orders_manual; DROP TABLE IF EXISTS public.shopify_all_orders; CREATE TABLE public.shopify_all_orders AS SELECT ao.*, UPPER(shopifyql.shopifyql_mapped_channel) shopifyql_mapped_channel, UPPER(shopifyql.shopifyql_mapped_source) shopifyql_mapped_source, UPPER(shopifyql.firstvisit_utm_source) shopifyql_firstvisit_utm_source, UPPER(shopifyql.firstvisit_utm_campaign) shopifyql_firstvisit_utm_campaign, UPPER(shopifyql.lastvisit_utm_campaign) shopifyql_last_visit_utm_campaign, UPPER(shopifyql.last_moment_utm_source) shopifyql_last_moment_utm_source, UPPER(shopifyql.lastvisit_non_utm_source) shopifyql_last_visit_non_utm_source, UPPER(shopifyql.last_moment_utm_medium) shopifyql_last_moment_utm_medium, UPPER(shopifyql.firstvisit_utm_medium) shopifyql_firstvisit_utm_medium, shopifyql.moments_count::FLOAT / COUNT(1) OVER (PARTITION BY ao.name) moments_count, shopifyql.daystoconvert::FLOAT / COUNT(1) OVER (PARTITION BY ao.name) daystoconvert, UPPER(checkout.checkout_utm_source) checkout_utm_source, UPPER(checkout.checkout_utm_medium) checkout_utm_medium, UPPER(COALESCE(checkout.checkout_utm_source, shopifyql.shopifyql_unmapped_last_source)) as utm_source_temp, UPPER(COALESCE(checkout.checkout_utm_medium, shopifyql.shopifyql_unmapped_last_medium)) as utm_medium_temp, UPPER(checkout.checkout_utm_content) checkout_utm_content, UPPER(checkout.checkout_mapped_channel) checkout_mapped_channel, UPPER(checkout.checkout_mapped_source) checkout_mapped_source, UPPER(referrer_name) referrer_name, UPPER(COALESCE(shopifyql_mapped_channel, checkout.checkout_mapped_channel)) channel_temp, UPPER(checkout.checkout_utm_campaign) checkout_utm_campaign, UPPER(COALESCE(lastvisit_utm_campaign, checkout.checkout_utm_campaign)) final_utm_campaign, UPPER(COALESCE(shopifyql_mapped_source, checkout.checkout_mapped_source, shopifyql.shopifyql_unmapped_last_source)) final_utm_source, UPPER(COALESCE(shopifyql_mapped_channel, checkout.checkout_mapped_channel, shopifyql.shopifyql_unmapped_last_source)) final_utm_channel FROM ( SELECT *, CASE WHEN LOWER(source_name) LIKE \'%pos%\' THEN \'SHOPIFY POS\' ELSE \'WEBSITE\' END AS shop_name FROM public.Tuco_Kids_new_shopify_orders_manual ) ao LEFT JOIN public.tuco_kids_shopify_utm_parameters shopifyql ON ao.name = shopifyql.name LEFT JOIN public.tuco_kids_checkout_source checkout ON ao.id = checkout.id ; DROP TABLE IF EXISTS public.shopify_all_products; CREATE TABLE public.shopify_all_products AS SELECT *, \'WEBSITE\' AS shop_name FROM public.Shopify_Tuco_Kids_products; DROP TABLE IF EXISTS public.shopify_all_products_variants; CREATE TABLE public.shopify_all_products_variants AS SELECT *, \'WEBSITE\' AS shop_name FROM public.Shopify_Tuco_Kids_products_variants; DROP TABLE IF EXISTS public.shopify_all_customers_addresses; CREATE TABLE public.shopify_all_customers_addresses AS SELECT *, \'WEBSITE\' AS shop_name FROM public.Shopify_Tuco_Kids_customers_addresses; DROP TABLE IF EXISTS public.shopify_all_orders_items_discount; CREATE TABLE public.shopify_all_orders_items_discount AS SELECT a.*, b.discount_codes from (select o.id AS order_id, li.id::VARCHAR AS line_item_id, SUM(da.amount::FLOAT) AS discount FROM public.shopify_all_orders o, o.line_items li, li.discount_allocations da GROUP BY 1,2) a left join (select o.id AS order_id, dc.code::VARCHAR AS discount_codes FROM public.shopify_all_orders o, o.discount_codes dc ) b on a.ordeR_id = b.order_id ; DROP TABLE IF EXISTS public.shopify_all_orders_items_tax; CREATE TABLE public.shopify_all_orders_items_tax AS SELECT order_id, line_item_id, SUM(CAST(c.price AS FLOAT)) AS tax, AVG(CAST(c.rate AS FLOAT)) AS tax_rate FROM ( SELECT a.id AS order_id, b.id AS line_item_id, b.tax_lines AS tax_lines FROM public.shopify_all_orders a CROSS JOIN a.line_items b ) x CROSS JOIN x.tax_lines c GROUP BY order_id, line_item_id; DROP TABLE IF EXISTS public.shopify_all_refunds; CREATE TABLE public.shopify_all_refunds AS WITH refund_line_items AS ( SELECT refunds.order_id, line_items.line_item_id, refunds.created_at as refund_date, SUM(CAST(line_items.quantity AS FLOAT)) as refund_quantity, SUM(CAST(line_items.subtotal AS FLOAT)) as refund_subtotal FROM public.shopify_all_orders a CROSS JOIN a.refunds refunds CROSS JOIN refunds.refund_line_items line_items WHERE refunds.order_id IS NOT NULL GROUP BY 1, 2, 3 ), order_adjustments AS ( SELECT refunds.order_id, refunds.created_at AS adjustment_date, SUM(CAST(order_adj.amount AS FLOAT)) adjustment FROM public.shopify_all_orders a CROSS JOIN a.refunds refunds CROSS JOIN refunds.order_adjustments order_adj GROUP BY 1, 2 ), adj_refund AS ( SELECT DISTINCT order_id, line_item_id, date FROM ( SELECT COALESCE(rl.order_id, oa.order_id) order_id, rl.line_item_id, CASE WHEN rl.refund_date = oa.adjustment_date THEN rl.refund_date ELSE COALESCE(oa.adjustment_date, rl.refund_date) END as date FROM refund_line_items rl FULL OUTER JOIN order_adjustments oa ON rl.order_id = oa.order_id ) ), refund_summary AS ( SELECT ar.order_id, ar.line_item_id, ar.date, COALESCE(rl.refund_quantity, 0) refund_quantity, COALESCE(rl.refund_subtotal, 0) refund_subtotal, COALESCE(oa.adjustment::FLOAT / COUNT(1) OVER (PARTITION BY ar.order_id, ar.date), 0) as adjustment_amount, (COALESCE(rl.refund_subtotal, 0) - COALESCE(COALESCE(oa.adjustment::FLOAT / COUNT(1) OVER (PARTITION BY ar.order_id, ar.date), 0), 0)) total_refund FROM adj_refund ar LEFT JOIN refund_line_items rl ON ar.order_id = rl.order_id AND ar.date = rl.refund_date AND ar.line_item_id = rl.line_item_id LEFT JOIN order_adjustments oa ON ar.order_id = oa.order_id AND ar.date = oa.adjustment_date ), aggregate_summary AS ( SELECT order_id, line_item_id, date, SUM(COALESCE(refund_quantity, 0)) AS refund_quantity, SUM(COALESCE(total_refund, 0)) AS refund_amount, SUM(COALESCE(adjustment_amount, 0)) AS adjustment_amount, SUM(COALESCE(refund_subtotal, 0)) AS refund_before_adjustment FROM refund_summary GROUP BY order_id, line_item_id, date ) SELECT asum.order_id, asum.line_item_id, MIN(CAST(asum.date AS DATE)) as refund_date, SUM(asum.refund_quantity) AS quantity, SUM(asum.refund_amount) AS amount, SUM(asum.adjustment_amount) AS adjustment_amount, SUM(asum.refund_before_adjustment) AS refund_before_adjustment FROM aggregate_summary asum GROUP BY asum.order_id, asum.line_item_id; DROP TABLE IF EXISTS public.shopify_all_orders_fulfillment; CREATE TABLE public.shopify_all_orders_fulfillment AS WITH unnested_orders AS ( SELECT fulfillment.order_id, li.id line_item_id, fulfillment.line_items AS line_item, fulfillment.tracking_number::varchar AS awb, fulfillment.tracking_company::varchar AS courier, fulfillment.shipment_status::varchar AS shipping_status, fulfillment.updated_at::timestamp AS shipping_status_update_date, fulfillment.tracking_url::varchar tracking_url, fulfillment.created_at AS shipping_created_at, ROW_NUMBER() OVER (PARTITION BY fulfillment.order_id, li.id ORDER BY fulfillment.updated_at DESC) rw FROM public.shopify_all_orders o, o.fulfillments fulfillment, fulfillment.line_items li WHERE LOWER(fulfillment.status::varchar) NOT LIKE \'%cancel%\' ) SELECT * FROM unnested_orders WHERE rw = 1; DROP TABLE IF EXISTS public.shopify_all_orders_shipping_lines_discount; CREATE TABLE public.shopify_all_orders_shipping_lines_discount AS SELECT id as order_id, SUM(CAST(da.amount AS FLOAT)) AS total_shipping_discount FROM public.shopify_all_orders o, o.shipping_lines sl, sl.discount_allocations da GROUP BY 1; DROP TABLE IF EXISTS public.shopify_all_orders_items; CREATE TABLE public.shopify_all_orders_items AS WITH cte AS ( SELECT shop_name, CAST(id AS VARCHAR) AS order_id, name AS order_name, customer, customer.default_address.name AS name, phone, email, tags, a.id AS line_item_id, a.sku, a.product_id, a.title AS product_name, currency, cancelled_at, CASE WHEN cancelled_at IS NOT NULL THEN \'CANCELLED\' ELSE \'SHOPIFY_PROCESSED\' END AS order_status, created_at::VARCHAR AS order_timestamp, CAST(a.price AS FLOAT) * CAST(a.quantity AS FLOAT) AS line_item_sales, (CAST(total_shipping_price_set.presentment_money.amount AS FLOAT) / COUNT(id) OVER (PARTITION BY id)) AS shipping_price, CAST(a.price AS FLOAT) / (1 + CAST(a.tax_lines.rate AS FLOAT)) AS price_before_tax, CAST(a.quantity AS INT) AS quantity, moments_count, daystoconvert, shopifyql_last_visit_utm_campaign, shopifyql_firstvisit_utm_campaign, shopifyql_firstvisit_utm_source, shopifyql_mapped_source, shopifyql_mapped_channel, shopifyql_last_moment_utm_source, shopifyql_last_visit_non_utm_source, shopifyql_last_moment_utm_medium, shopifyql_firstvisit_utm_medium, checkout_utm_source, checkout_utm_medium, utm_source_temp, utm_medium_temp, checkout_utm_campaign, checkout_utm_content, final_utm_campaign, final_utm_channel, channel_temp, final_utm_source, referrer_name, checkout_mapped_source, checkout_mapped_channel, payment_gateway_names AS gateway, shipping_address, so.shipping_address.zip::varchar pincode, source_name, location_id, CASE WHEN (LOWER((payment_gateway_names::varchar)) LIKE \'%cod%\' OR LOWER((payment_gateway_names::varchar)) LIKE \'%cash%\') THEN \'COD\' ELSE \'PREPAID\' END payment_mode FROM public.shopify_all_orders so, so.line_items a ) SELECT cte.*, COALESCE(t.tax_rate, 0) AS tax_rate, COALESCE(d.discount, 0) AS discount, d.discount_codes, cte.line_item_sales AS gross_sales_after_tax, CASE WHEN COALESCE(t.tax, 0) = 0 THEN (COALESCE(cte.line_item_sales, 0) - COALESCE(t.tax, 0)) ELSE cte.line_item_sales / (1 + COALESCE(t.tax_rate, 0)) END AS gross_sales_before_tax, CASE WHEN COALESCE(t.tax, 0) = 0 THEN COALESCE(d.discount, 0) ELSE COALESCE(d.discount, 0) / (1 + COALESCE(t.tax_rate, 0)) END AS discount_before_tax, CASE WHEN COALESCE(t.tax, 0) = 0 THEN cte.line_item_sales - COALESCE(d.discount, 0) ELSE cte.line_item_sales / (1 + COALESCE(t.tax_rate, 0)) - COALESCE(d.discount, 0) / (1 + COALESCE(t.tax_rate, 0)) END AS net_sales_before_tax, COALESCE(t.tax, 0) AS tax, CASE WHEN COALESCE(t.tax, 0) = 0 THEN cte.line_item_sales - COALESCE(d.discount, 0) - COALESCE(sd.total_shipping_discount::FLOAT / COUNT(1) OVER (PARTITION BY cte.order_id), 0) + COALESCE(t.tax, 0) + cte.shipping_price ELSE cte.line_item_sales / (1 + COALESCE(t.tax_rate, 0)) - COALESCE(d.discount, 0) / (1 + COALESCE(t.tax_rate, 0)) - COALESCE(sd.total_shipping_discount::FLOAT / COUNT(1) OVER (PARTITION BY cte.order_id), 0) + COALESCE(t.tax, 0) + cte.shipping_price END - COALESCE(r.refund_before_adjustment, 0) - COALESCE(re.refund_before_adjustment::FLOAT / COUNT(1) OVER (PARTITION BY cte.order_id), 0) AS total_sales, CASE WHEN r.quantity IS NOT NULL THEN 1 ELSE 0 END AS is_refund, r.refund_date, r.quantity AS refund_quantity, r.refund_before_adjustment AS refund_value, COALESCE(r.refund_date::DATE, re.refund_date::DATE) as refund_date_final, COALESCE(re.refund_before_adjustment::FLOAT, 0) / COUNT(1) OVER (PARTITION BY cte.order_id) refund_amount_without_lineitem, f.awb, f.courier, f.shipping_status, f.shipping_status_update_date, f.tracking_url, f.shipping_created_at, COALESCE(sd.total_shipping_discount::FLOAT / COUNT(1) OVER (PARTITION BY cte.order_id), 0) AS total_shipping_discount FROM cte LEFT JOIN public.shopify_all_orders_items_tax t ON cast(cte.order_id as varchar) = CAST(t.order_id AS VARCHAR) AND cast(cte.line_item_id as varchar) = CAST(t.line_item_id AS VARCHAR) LEFT JOIN public.shopify_all_orders_items_discount d ON cast(cte.order_id as varchar) = CAST(d.order_id AS VARCHAR) AND cast(cte.line_item_id as varchar) = CAST(d.line_item_id AS VARCHAR) LEFT JOIN public.shopify_all_refunds r ON cast(cte.order_id as varchar) = CAST(r.order_id AS VARCHAR) AND cast(cte.line_item_id as varchar) = CAST(r.line_item_id AS VARCHAR) LEFT JOIN public.shopify_all_refunds re ON cast(cte.order_id as varchar) = CAST(re.order_id AS VARCHAR) AND re.line_item_id IS NULL LEFT JOIN public.shopify_all_orders_fulfillment f ON cast(cte.order_id as varchar) = CAST(f.order_id AS VARCHAR) AND cast(cte.line_item_id as varchar) = CAST(f.line_item_id AS VARCHAR) LEFT JOIN public.shopify_all_orders_shipping_lines_discount sd ON cast(cte.order_id as varchar) = CAST(sd.order_id AS VARCHAR);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

